function productionHorizontalReview(host,locked){
 const form=host.querySelector('#dossier-prepare'),groups=[...host.querySelectorAll('.production-review-sections>details')],keys=['input','structure','operations','quantities'],labels=['1. Đầu vào và bản vẽ','2. Cấu thành sản phẩm','3. Công đoạn và định mức','4. Khai triển và hao hụt'];
 for(const name of ['requirements','noDrawingReason']){const input=form.elements.namedItem(name);if(input){input.setAttribute('form','dossier-prepare');input.disabled=locked;groups[0].append(input.closest('label')||input);}}
 const nav=document.createElement('div');nav.className='production-review-nav';nav.setAttribute('aria-label','Bốn mục rà soát sản xuất');
 groups.forEach((section,i)=>{section.querySelector('summary').textContent=labels[i];const button=document.createElement('button');button.type='button';button.dataset.reviewTab=keys[i];button.textContent=labels[i]+(section.querySelector('input[type=checkbox]')?.checked?' · Đã xác nhận':' · Chưa xác nhận');button.onclick=()=>{groups.forEach(g=>g.hidden=false);section.scrollIntoView({block:'start',behavior:'smooth'});[...nav.children].forEach((b,k)=>b.classList.toggle('active',k===i));};nav.append(button);section.open=true;section.hidden=false;const check=section.querySelector('.production-check'),save=document.createElement('button');save.type='submit';save.setAttribute('form','dossier-prepare');save.textContent='Lưu xác nhận mục này';save.dataset.reviewSection=keys[i];save.disabled=locked;check.after(save);if(i===2){const draft=document.createElement('button');draft.type='submit';draft.setAttribute('form','dossier-prepare');draft.dataset.reviewSection='operations';draft.dataset.reviewDraft='';draft.textContent='Lưu thông tin đã nhập';draft.disabled=locked;save.before(draft);}if(i>0){const edit=document.createElement('button');edit.type='button';edit.textContent='Khai / sửa và lập bảng kiến nghị';edit.disabled=locked;edit.onclick=()=>window.open('/?production-editor='+encodeURIComponent(Production.job.id)+'&section='+['intake','bom','operations','waste'][i],'_blank','noopener');section.querySelector('summary').after(edit);}});
 groups[3].insertAdjacentHTML('afterbegin','<h4>Phương án khai triển của lệnh</h4><p>Mạch cắt: '+pe(Production.job.packet.kerf)+' mm. Thay đổi khai triển cần gửi bảng kiến nghị trước khi áp dụng.</p>'+Production.job.packet.cutting.map(productionCut).join(''));
 host.querySelector('.production-review-input').before(nav);nav.firstChild.classList.add('active');host.querySelector('.production-review-flow').innerHTML='<strong>1. Nội dung lệnh</strong><span>→</span><strong>2. Rà soát điều kiện</strong><span>→</span><strong>3. Triển khai sản xuất</strong>';host.querySelector('h3').textContent='Rà soát điều kiện sản xuất';
 const feedback=Production.dossierSaveFeedback;if(feedback?.id===Production.job.id){const notice=document.createElement('div');notice.className='notice';notice.setAttribute('role','status');notice.dataset.reviewFeedback='';notice.innerHTML='<strong>'+pe(feedback.text)+'</strong>';for(const key of feedback.missing){const index=keys.indexOf(key);if(index<0)continue;const b=document.createElement('button');b.type='button';b.textContent='Mở '+labels[index];b.onclick=()=>nav.children[index].click();notice.append(b);}for(const i of feedback.operations||[]){const b=document.createElement('button');b.type='button';b.textContent='Bổ sung '+(Production.job.packet.operations[i]?.name||'nguyên công');b.onclick=()=>{nav.children[2].click();const op=host.querySelector('[data-review-operation="'+i+'"]');op.open=true;op.scrollIntoView({block:'center'});};notice.append(b);}if(feedback.blankWarning)notice.insertAdjacentHTML('beforeend','<p>Kích thước khai triển cần được duyệt trước khi áp dụng.</p>');nav.after(notice);delete Production.dossierSaveFeedback;}
 if(Production.dossierReturnGroup){nav.children[keys.indexOf(Production.dossierReturnGroup)]?.click();delete Production.dossierReturnGroup;}
}

function productionActor(a,empty){return a?pe(a.name||a.actor||'Chưa ghi nhận tên')+' · '+pe(TPDisplay.date(a.at,true)):pe(empty);}
function productionDocumentGroups(files,scope,d){const groups=[['contract','Bản vẽ ký hợp đồng'],['shop','Bản vẽ shop phục vụ sản xuất'],['other','Tài liệu khác'],['unclassified','Tài liệu chưa phân loại']];return groups.map(([key,label])=>{const rows=files.filter(f=>(f.category||'unclassified')===key);if(key==='unclassified'&&!rows.length)return '';return '<section class="production-document-group"><h4>'+label+'</h4>'+(rows.length?rows.map(f=>'<p><strong>'+pe(f.name)+'</strong>'+ (f.revision?' · Phiên bản '+pe(f.revision):'')+(f.note?' · '+pe(f.note):'')+(f.actor?'<br><small>Bổ sung bởi '+productionActor(f,'')+'</small>':'')+(files.some(x=>x.supersedes===f.id)?' · Đã có bản thay thế':'')+(f.storage==='server'?' <button type="button" data-'+scope+'-file="'+pe(f.id)+'">Tải tài liệu</button>':' · Chưa có tệp trên máy chủ')+(scope==='dossier'&&d.canEdit?'<label>Nhóm tài liệu <select data-document-category="'+pe(f.id)+'"><option value="">Chọn nhóm</option>'+groups.filter(([k])=>k!=='unclassified').map(([k,v])=>'<option value="'+k+'" '+(k===f.category?'selected':'')+'>'+v+'</option>').join('')+'</select></label>':'')+'</p>').join(''):'<p class="muted">Chưa có tài liệu trong nhóm này.</p>')+'</section>';}).join('');}
function productionTrace(d){return '<section class="production-trace"><h3>Dẫn chiếu và lịch sử thay đổi</h3>'+Object.entries(d.confirmations||{}).filter(([,v])=>v).map(([k,v])=>'<p>'+pe(({input:'Bản vẽ',structure:'Thông số',operations:'Nguyên công và máy',quantities:'Vật tư'})[k]||k)+' · Xác nhận bởi: '+productionActor(v,'Chưa xác nhận')+'</p>').join('')+((d.trace?.changes||[]).length?(d.trace.changes||[]).map(c=>'<article><strong>'+pe(c.reason)+'</strong><p>'+pe(({pending:'Chờ xác nhận kỹ thuật',confirmed:'Chờ duyệt',approved:'Đã áp dụng',rejected:'Đã trả lại'})[c.state]||c.state)+' · Mã đề nghị: '+pe(c.id)+'</p><p>Căn cứ: '+pe(c.reference||'Theo lý do đề nghị')+'</p><p>Lập bởi: '+productionActor({name:c.actor,at:c.at},'Chưa ghi nhận')+'</p><p>Xác nhận kỹ thuật: '+productionActor(c.technical,'Chưa xác nhận')+'</p><p>Duyệt: '+(c.state==='approved'?productionActor({name:c.reviewedBy,at:c.reviewedAt},'Chưa duyệt'):'Chưa duyệt áp dụng')+(c.appliedVersion?' · Phiên bản lệnh '+pe(c.appliedVersion):'')+'</p></article>').join(''):'<p>Chưa có đề nghị thay đổi.</p>')+'</section>';}

function productionProcessOverview(j){
 const el=document.querySelector('#production-operations');if(!el)return;
 const rows=j.packet.operations.map((o,i)=>{const v=j.progress.operations.find(x=>x.id===o.id)||{},person=Production.people.find(x=>x.id===v.assignee)?.name;return [pe(i+1),'<strong>'+pe(o.name)+'</strong><br>'+pe(o.object),pe(person||'Chưa phân công'),pe(v.machine||o.machine||'Chưa chọn máy'),pe(v.output||0)+' / '+pe(o.quantity)+' '+pe(o.outputUnit||'chi tiết'),pe(v.deadline||j.progress.deadline||'Chưa có tiến độ'),pe(productionStatus[v.status]||'Chưa bắt đầu'),pe(v.issue||v.waitReason||''),'<button type="button" data-process-operation="'+pe(o.id)+'">Khai báo</button>'];});
 rows.push([pe(rows.length+1),'QC',pe(j.progress.qc.actor||'Chưa ghi nhận'),'',pe(j.progress.qc.passed||0)+' đạt / '+pe(j.progress.qc.rejected||0)+' không đạt',pe(j.progress.deadline||''),j.progress.qc.at?'Đã ghi nhận QC':'Chờ QC',pe(j.progress.qc.note||''),'<button data-production-tab="qc">Mở QC</button>']);
 rows.push([pe(rows.length+1),'Hoàn thành',pe(j.progress.assigneeName||'Chưa phân công'),'','',pe(j.progress.deadline||''),j.state==='completed'?'Đã hoàn thành':'Chờ xác nhận riêng','','<button data-production-tab="qc">Xác nhận hoàn thành</button>']);
 el.insertAdjacentHTML('afterbegin','<section class="production-process-overview"><h3>Quy trình sản xuất của lệnh</h3><p>Theo thứ tự công nghệ đã duyệt. Khối lượng ghi nhận từ bước sau không thay thế duyệt hoàn thành, đối soát kho hoặc QC.</p>'+(!j.packet.flowApproved?'<p class="notice">Chưa duyệt tiến trình công nghệ. <button type="button" data-flow-open>Lập / rà soát quy trình</button></p>':'<p>Đã duyệt bởi '+pe(j.packet.flowApproved.admin)+' · '+pe(TPDisplay.date(j.packet.flowApproved.at,true))+'</p>')+opsTable(['Bước','Công đoạn / đối tượng','Chịu trách nhiệm','Máy','Sản lượng','Tiến độ','Trạng thái','Vướng mắc','Thao tác'],rows)+'<details><summary>Tham khảo chuỗi công đoạn</summary><p>Cắt → Tiện → Phay → Hàn → Sơn → Lắp ráp → QC → Hoàn thành. Khai các công đoạn thực tế của sản phẩm, sắp thứ tự và gửi duyệt tại phần công nghệ; QC và hoàn thành là hai bước kiểm soát riêng.</p></details></section>');
 el.querySelectorAll('[data-process-operation]').forEach(b=>b.onclick=()=>{const form=[...el.querySelectorAll('[data-operation]')].find(f=>f.dataset.operation===b.dataset.processOperation);form?.scrollIntoView({block:'start',behavior:'smooth'});form?.querySelector('select')?.focus({preventScroll:true});});
}

// Keep a single set of controls: compact cells move the original fields, preserving
// the reviewed equipment, version checks and consolidated approval handlers.
function productionUnifiedReview(host,j,d,locked){
 host.classList.add('production-unified-review');
 const groups=[...host.querySelectorAll('.production-review-sections>details')],structure=groups[1],operations=groups[2],quantities=groups[3],table=structure.querySelector('table'),rows=productionPreparationRows(j,d.source);
 table.classList.add('production-review-grid');
 const labels=['Sản phẩm / cấu kiện / vật tư · Kích thước chi tiết (mm)','ĐVT / số lượng','Kích thước khai triển (mm)','Công đoạn / máy / nơi thực hiện','Khối lượng / diện tích phôi','Ghi chú'];
 table.tHead.rows[0].innerHTML=labels.map(l=>'<th>'+pe(l)+'</th>').join('');
 const fmt=v=>Number.isFinite(v)?v.toLocaleString('vi-VN',{maximumFractionDigits:3}):'—';
 [...table.tBodies[0].rows].forEach((tr,index)=>{
  const r=rows[index],n=r.node,m=r.material;tr.dataset.reviewRow=n.id;tr.classList.add('review-row-'+n.kind);
  const notes=tr.cells[3];notes.remove();const opCell=tr.insertCell(),mass=tr.insertCell();tr.append(notes);
  notes.innerHTML=productionDetailNotes(n)||'—';
  const edit=document.createElement('button');edit.type='button';edit.textContent='Sửa khai báo';edit.dataset.reviewEdit=n.id;edit.disabled=locked;edit.onclick=()=>window.open('/?production-editor='+encodeURIComponent(j.id)+'&section=bom&node='+encodeURIComponent(n.id),'_blank','noopener');tr.cells[0].append(edit);
  const blank=tr.querySelector('[data-review-blank]');if(blank){const details=document.createElement('details');details.className='review-cell-editor';details.innerHTML='<summary><strong>'+pe([m.dimensions.length,m.dimensions.width].filter(v=>v>0).join(' × '))+' mm</strong><span class="review-edit-label">Sửa khai báo</span></summary>';blank.before(details);details.append(blank);blank.querySelector('[data-blank-propose]')?.setAttribute('hidden','');}
  j.packet.operations.forEach((o,i)=>{if(o.nodeId!==n.id)return;const details=operations.querySelector('[data-review-operation="'+i+'"]');if(!details)return;details.open=false;
   const v=d.equipment.find(x=>x.operationId===o.id)||j.progress.operations.find(x=>x.id===o.id)||{},machine=v.machine||o.machine||d.machines.find(x=>x.id===(v.machineId||o.machineId))?.name;
   details.querySelector('summary').innerHTML='<strong>'+pe(o.name)+'</strong><small>'+pe(o.mode==='outside'?'Thuê ngoài':'Tại xưởng')+(machine?' · '+pe(machine):' · Chưa chọn máy')+'</small><small>'+pe(o.workQuantity)+' '+pe(o.unit)+'</small><span class="review-edit-label">Sửa khai báo</span>';
   const method=details.querySelector('[name="method'+i+'"]'),advanced=document.createElement('details');advanced.className='review-method';advanced.innerHTML='<summary>Phương pháp / ghi chú đã khai</summary>';if(method){advanced.append(method.closest('label')||method);details.append(advanced);}opCell.append(details);
  });if(!opCell.children.length)opCell.textContent='—';
  // Packet dimensions are totals for the lot; do not multiply by count again.
  const materials=m?[m]:(()=>{const ids=new Set();const walk=x=>{ids.add(x.id);(x.children||[]).forEach(walk);};walk(n);return j.packet.materials.filter(x=>ids.has(x.id));})();
  const weight=materials.reduce((sum,x)=>sum+(x.dimensions.weight||0),0),area=materials.reduce((sum,x)=>sum+((x.dimensions.blankArea??(x.material.shape==='sheet'?x.dimensions.length*x.dimensions.width*x.count/1e6:x.dimensions.area))||0),0);
  mass.innerHTML=materials.length?'<div>'+fmt(weight)+' kg</div><div>'+fmt(area)+' m²</div>'+(m?'':'<small>Tổng cấu thành</small>'):'—';
 });
 operations.querySelector('.dossier-detail-table')?.remove();
 operations.querySelector('[data-review-operation-refresh]')?.setAttribute('hidden','');
 quantities.querySelector('table')?.closest('.table-scroll')?.remove();
 // This table has replaced all three repeated technical lists.
 structure.querySelector('summary').textContent='Cấu thành sản phẩm và công đoạn · Rà soát trên cùng một trang';
 operations.querySelector('summary').textContent='Xác nhận công đoạn và máy';
 host.querySelectorAll('.production-review-sections>details>button').forEach(b=>{if(b.textContent==='Khai / sửa và lập bảng kiến nghị')b.hidden=true;});
 const intro=document.createElement('p');intro.className='muted';intro.textContent='Mở Sửa khai báo tại nội dung cần điều chỉnh. Thay đổi kích thước và máy được tổng hợp thành kiến nghị; chỉ áp dụng sau khi duyệt.';table.parentElement.before(intro);
 host.querySelectorAll('[data-review-operation] select').forEach(select=>select.addEventListener('change',()=>{const i=Number(select.closest('[data-review-operation]').dataset.reviewOperation),machine=d.machines.find(m=>m.id===select.value),name=host.querySelector('[name="machine'+i+'"]');if(machine&&name)name.value=machine.name;}));
}
